    /** Crea una nueva instancia. */
    public ZafCom112(ZafParSis obj)
    {  
        try
        {
            objParSis=(ZafParSis)obj.clone();
            if ( (objParSis.getCodigoEmpresa()==objParSis.getCodigoEmpresaGrupo()) )
            { 
                initComponents();
                if (!configurarFrm())
                    exitForm();
            }
            else
            {
                mostrarMsgInf("<HTML>Este programa sólo se puede ejecutar a través del GRUPO.</HTML>");
                dispose();
            }
        }
        catch (CloneNotSupportedException e)
        {
            this.setTitle(this.getTitle() + " [ERROR]");
        }
    }    
    
private void guardarTblHist() {
    try {
        int intNumFil = objTblMod.getRowCountTrue();
        int intNumCol = objTblMod.getColumnCount();

        for (int i = 0; i < intNumFil; i++) {
            for (int j = intNumColIniProAnu; j < intNumCol; j++) {

                Object objVal = objTblMod.getValueAt(i, j);
                BigDecimal bgdValor;

                // Conversión segura
                if (objVal == null || objVal.toString().trim().equals("")) {
                    bgdValor = BigDecimal.ZERO;
                } else {
                    try {
                        bgdValor = new BigDecimal(objVal.toString().trim());
                    } catch (NumberFormatException e) {
                        bgdValor = BigDecimal.ZERO; // Si no es número
                    }
                }

                // Clave tipo "fila,columna"
                String clave = i + "," + j;

                // Crear objeto Com112_hist con valor numérico
                Com112_hist dato = new Com112_hist(bgdValor);

                // Guardar en el mapa
                dataMapHistCol.put(clave, dato);
            }
        }

        lblMsgSis.setText("Se procesaron " + tblDat.getRowCount() + " registros para histórico.");

    } catch (Exception e) {
        objUti.mostrarMsgErr_F1(this, e);
    }
}

private String construirJsonItemsDesdeTabla() {
    StringBuilder sb = new StringBuilder();
    sb.append("{\"items\": [");
    int contador = 0;
    try {
            for (int i = 0; i < objTblMod.getRowCountTrue(); i++) 
            {
                // Obtiene el valor usando tu función existente
                String item = objUti.parseString(objTblMod.getValueAt(i, INT_TBL_DAT_COD_ALT_ITM));

                // Solo agrega si no está vacío o es "0"
                if (!item.isEmpty() && !item.equals("0")) {
                    if (contador > 0) {
                        sb.append(", ");
                    }
                    sb.append("\"").append(item).append("\"");
                    contador++;
                }
            }
    } catch (Exception e) {
        System.err.println("Error al construir JSON de ítems: " + e.getMessage());
        e.printStackTrace();
    }

    sb.append("]}");
    return sb.toString();
}

private String construirJsonItemsEnCadena() {
    StringBuilder sb = new StringBuilder();
    StringJoiner joiner = new StringJoiner(",");

    try {
        for (int i = 0; i < objTblMod.getRowCountTrue(); i++) {
            String item = objTblMod.getValueAt(i, INT_TBL_DAT_COD_ALT_ITM).toString();
            if (item != null && !item.trim().isEmpty() && !"0".equals(item.trim())) {
                joiner.add(item.trim());
            }
        }
    } catch (Exception e) {
        System.err.println("Error al construir JSON de ítems: " + e.getMessage());
        e.printStackTrace();
    }

    sb.append("{\"items\":\"")
      .append(joiner.toString())
      .append("\"}");

    return sb.toString();
}


    
    
private BigDecimal obtenerTblHist(String llave) {
    BigDecimal bdgValor = BigDecimal.ZERO;  // Valor por defecto

    try {
        if (dataMapHistCol != null && dataMapHistCol.containsKey(llave)) {
            Com112_hist dato = dataMapHistCol.get(llave);
            if (dato != null && dato.getBgd_valor() != null) {
                // Si el getter devuelve String, conviértelo
                try {
                    bdgValor = new BigDecimal(dato.getBgd_valor().toString().trim());
                } catch (NumberFormatException e) {
                    bdgValor = BigDecimal.ZERO;
                }
            }
        }
    } catch (Exception e) {
        System.err.println("Error en obtenerTblHist(" + llave + "): " + e.getMessage());
        bdgValor = BigDecimal.ZERO;
    }

    return bdgValor;
}


