// Variable de control para evitar múltiples ejecuciones.
// Renderer para cambiar el color de la fila basado en una condición
private void configurarColorRangoColumnas(int columnaInicio, int columnaFin) {
    // Recorremos el rango de columnas desde columnaInicio hasta columnaFin
    for (int col = columnaInicio; col <= columnaFin; col++) {
        tblFix.getColumnModel().getColumn(col).setCellRenderer(new javax.swing.table.DefaultTableCellRenderer() {
            @Override
            public java.awt.Component getTableCellRendererComponent(javax.swing.JTable table, Object value, boolean isSelected, boolean hasFocus, int row, int column) {
                java.awt.Component comp = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);

                try {
                    // Obtener el valor de la columna "inactivo" para decidir el color
                    int inactivo = Integer.parseInt(objUti.parseString(objTblModFix.getValueAt(row, INT_TBL_DAT_FIX_ITEM_EL)));
                    int detgrpu = Integer.parseInt(objUti.parseString(objTblModFix.getValueAt(row, INT_TBL_DAT_FIX_DET_GRP)));
                    int cabgrpu = Integer.parseInt(objUti.parseString(objTblModFix.getValueAt(row, INT_TBL_DAT_FIX_GRP)));

                    // Cambiar el color de fondo según el valor de "inactivo"
                    if ((inactivo == 1))//es inactivo 
                    {
                        if (detgrpu !=0) // es inactivo y esta en un detalle de grupo
                        {
                            comp.setBackground(new Color(255, 200, 150));
                            comp.setForeground(java.awt.Color.BLACK);                                                    
                        }
                        else//es inactivo y no tiene grupo
                        {
                            comp.setBackground(new Color(255, 102, 102));
                            comp.setForeground(java.awt.Color.BLACK);                                                    
                        }    
                    } 
                    else // es activo
                    {
                        if  (cabgrpu !=0) //es activo y  esta en grupo
                        {
                            comp.setBackground(java.awt.Color.LIGHT_GRAY);
                            comp.setForeground(java.awt.Color.BLACK);                            
                        }
                        else// es activo 
                        {
                            comp.setBackground(java.awt.Color.WHITE);
                            comp.setForeground(java.awt.Color.BLACK);
                        }    
                        
                    }
                    

                    // Si la celda está seleccionada, mantén el color de selección
                    if (isSelected) {
                        comp.setBackground(java.awt.Color.BLUE);
                        comp.setForeground(java.awt.Color.WHITE);
                    }
                } catch (Exception e) {
                    comp.setBackground(java.awt.Color.WHITE);
                    comp.setForeground(java.awt.Color.BLACK);
                    System.err.println("Error al pintar la columna: " + e.getMessage());
                }

                return comp;
            }
        });
    }

    // Refrescar la tabla para aplicar los cambios
    tblFix.repaint();
}

    
