    private boolean cargarAnios(int opcion)//chiqui_1
    {
        boolean blnRes=true;
        String strAniSel="";
        try
        {
            con=DriverManager.getConnection(objParSis.getStringConexion(), objParSis.getUsuarioBaseDatos(), objParSis.getClaveBaseDatos());
            conGP=DriverManager.getConnection(objParSis.getStringConexion_Dynamics2021(), objParSis.getUsuarioBaseDatos_Dynamics2021(), objParSis.getClaveBaseDatos_Dynamics2021());
            if (conGP!=null)
            {
                stmGP=conGP.createStatement();
                if(opcion==0)
                {
                    
                }
                else
                {
                    //Query original (1.0 seg):
//                    strSQL ="";
//                    strSQL+=" SELECT a1.co_emp, a1.ne_ani, a2.ne_aniSel";
//                    strSQL+=" FROM tbm_venMenInvBod AS a1 LEFT OUTER JOIN tbm_filAniSelCfgImp AS a2";
//                    strSQL+=" ON a1.ne_ani=a2.ne_aniSel";
//                    strSQL+=" WHERE a1.co_emp=" + objParSis.getCodigoEmpresa() + "";
//                    strSQL+=" GROUP BY a1.co_emp, a1.ne_ani, a2.ne_aniSel";
//                    strSQL+=" ORDER BY a1.ne_ani DESC";
                    //Query mejorado (0.4 seg):
                    strSQL ="";
//////                    strSQL+=" SELECT a1.co_emp, a1.ne_ani, a2.ne_aniSel";
//////                    strSQL+=" FROM (";
//////                    strSQL+=" SELECT co_emp, ne_ani";
//////                    strSQL+=" FROM tbm_venMenInvBod";
//////                    strSQL+=" WHERE co_emp=" + objParSis.getCodigoEmpresa() + "";
//////                    strSQL+=" GROUP BY co_emp, ne_ani";
//////                    strSQL+=" ) AS a1";
//////                    strSQL+=" LEFT OUTER JOIN tbm_filAniSelCfgImp AS a2 ON (a1.ne_ani=a2.ne_aniSel)";
//////                    strSQL+=" ORDER BY a1.ne_ani DESC";

////                    strSQL+=" SELECT 1 as co_emp,ne_ani, '' as ne_aniSel";
////                    strSQL+=" FROM (";
////                    strSQL+=" SELECT ne_ani";
////                    strSQL+=" FROM Dynamics2021..tbm_venMenInvBod";
////                    strSQL+=" ) AS a1";
////                    strSQL+=" GROUP BY a1.ne_ani";                    
////                    strSQL+=" ORDER BY a1.ne_ani DESC";
                    strSQL+=" SELECT 1 as co_emp, a1.ne_ani, a2.ne_aniSel \n";
                    strSQL+=" FROM Dynamics2021..tbm_venMenInvBod as a1 \n";
                    strSQL+="       LEFT OUTER JOIN Dynamics2021..tbm_filAniSelCfgImp AS a2 ON (a1.ne_ani=a2.ne_aniSel AND a2.co_usr = "+ objParSis.getCodigoUsuario() +" )";
                    strSQL+=" GROUP BY a1.ne_ani ,a2.ne_aniSel ";                    
                    strSQL+=" ORDER BY a1.ne_ani DESC";
                    
                    
                    rstGP=stmGP.executeQuery(strSQL);
                    while (rstGP.next())
                    {
                        vecRegHis=new Vector();
                        vecRegHis.add(INT_TBL_DAT_HIS_LIN,"");
                        vecRegHis.add(INT_TBL_DAT_HIS_CHK,"");
                        vecRegHis.add(INT_TBL_DAT_HIS_ANI,"" + rstGP.getString("ne_ani"));
                        vecRegHis.add(INT_TBL_DAT_HIS_NUM_MES,"");
                        vecRegHis.add(INT_TBL_DAT_HIS_MES,"");
                        strAniSel=rstGP.getObject("ne_aniSel")==null?"":rstGP.getString("ne_aniSel");
                        if(!strAniSel.equals(""))
                        {
                            //vecRegHis.setElementAt(new Boolean(true), INT_TBL_DAT_HIS_CHK);
                            vecRegHis.setElementAt(Boolean.TRUE, INT_TBL_DAT_HIS_CHK);
                            vecRegHis.setElementAt("M", INT_TBL_DAT_HIS_LIN);
                        }
                        vecDatHis.add(vecRegHis);
                    }
                    rstGP.close();
                    rstGP=null;
                    //Asignar vectores al modelo.
                    objTblModHis.setData(vecDatHis);
                    tblHis.setModel(objTblModHis);
                    vecDatHis.clear();
                }
                stmGP.close();
                stmGP=null;
                conGP.close();
                conGP=null;
            }
        }
        catch (java.sql.SQLException e)
        {
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        catch (Exception e)
        {
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }
    
