private boolean consultaConfExpoExcel()
    {
        boolean blnRes=false;
        int contador =0;
        String strSQL ="";
        java.sql.Connection conLoc; 
        java.sql.Statement stmLoc;
        java.sql.ResultSet rstLoc;          
        try
        {
            conLoc=DriverManager.getConnection(objParSis.getStringConexion_Dynamics2021(), objParSis.getUsuarioBaseDatos_Dynamics2021(), objParSis.getClaveBaseDatos_Dynamics2021());      
            if (conLoc!=null)
            {
                stmLoc=conLoc.createStatement();
                strSQL="";       
                strSQL+=" SELECT tx_deside    \n";
                strSQL+=" FROM  Dynamics2021.dbo.tbm_cabexpcol \n";
                strSQL+=" WHERE co_mnu = "+objParSis.getCodigoMenu() +"\n";
                strSQL+="       AND st_reg= 'A' and co_usrIng = "+objParSis.getCodigoUsuario() +"\n";
                strSQL+=" ORDER BY co_ide ASC ";   
                rstLoc=stmLoc.executeQuery(strSQL);   
            
                // Recorrer los resultados y añadir al combo
                if (rstLoc.next())
                    blnRes=true;
            }

            rstLoc=null;
            stmLoc=null;
            conLoc.close();
            conLoc=null;                            
        }
        catch (Exception e)
        {
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }

        /**
     * Esta función muestra un mensaje "showConfirmDialog". Presenta las opciones
     * Si y No. El usuario es quien determina lo que debe hacer el sistema
     * seleccionando una de las opciones que se presentan.
     */
    private int mostrarMsgCon(String strMsg)
    {
        String strTit;
        strTit="Mensaje del sistema Zafiro";
        return javax.swing.JOptionPane.showConfirmDialog(this,strMsg,strTit,javax.swing.JOptionPane.YES_NO_OPTION,javax.swing.JOptionPane.QUESTION_MESSAGE);
    }
    
