private void ProcesoColumnasEditables()
{
        if(objTblMod.getRowCountTrue()>0)
        {
            vecAux=new Vector();
            vecAux.add(""+(intNumColIniProAnu+7));
            
            if ((objParSis.getCodigoUsuario()==93) ||(objParSis.getCodigoUsuario()==1)   || (objParSis.getCodigoUsuario()==24)) 
                vecAux.add("" + (intNumColIniProAnu + 9)); // Indicar la columna a desbloquear
            
            objTblMod.addColumnasEditables(vecAux); 
            vecAux=null;
//                chkModPromedio.setEnabled(false);
//                chkModPromedio.setBackground(Color.red);
        }
} 

private void ProcesoColumnasNoEditables()
{
    if (objTblMod.getRowCountTrue() > 0)
    {
        Vector vecAux = new Vector();
        vecAux.add("" + (intNumColIniProAnu + 8)); // Indicar la columna a bloquear
        objTblMod.removeColumnasEditables(vecAux); // Llamar a la nueva función
        vecAux = null;
    }
}



