     private void ocultaColumnasPorFiltroAvanzado()
     {
            if(chkMosPed.isSelected()){
                for(int i=intNumColIniPedEmb; i<(intNumColFinPedEmb-1); i++){  //AZ: Se deja activa la creacion de Nota Pedido Previa y Totales de Pedido
                    objTblMod.removeSystemHiddenColumn(i, tblDat);
                    objTblModTot.removeSystemHiddenColumn(i, tblTotDat);
                }
            }
            else
            {
                // Ocultar ocultarPedidosCurso
                //for(int i=intNumColFinStk; i<(intNumColFinPedPre-1); i++){  ///JM
                for(int i=intNumColIniPedEmb; i<(intNumColFinPedEmb-1); i++){  //AZ: Se deja activa la creacion de Nota Pedido Previa y Totales de Pedido
                    objTblMod.addSystemHiddenColumn(i, tblDat);
                    objTblModTot.addSystemHiddenColumn(i, tblTotDat);
                }
            }  
     }
     
     private void ocultaColumnasPorCategoria(int tipo )
     {
                for(int i=intNumColIniCat; i<(intNumColFinCat-1); i++)
                {  
                    if (tipo ==1)
                    {
                        if(chkMosVta.isSelected())
                        {
                            objTblMod.removeSystemHiddenColumn(i, tblDat);
                            objTblModTot.removeSystemHiddenColumn(i, tblTotDat);                        

                        }                        
                        else
                        {
                            objTblMod.addSystemHiddenColumn(i, tblDat);
                            objTblModTot.addSystemHiddenColumn(i, tblTotDat);                            
                        }                        
                    }
                    
                    if (tipo ==2)
                    {
                        if(chkMosPes.isSelected())
                        {
                            objTblMod.removeSystemHiddenColumn(i, tblDat);
                            objTblModTot.removeSystemHiddenColumn(i, tblTotDat);                        

                        }                        
                        else
                        {
                            objTblMod.addSystemHiddenColumn(i, tblDat);
                            objTblModTot.addSystemHiddenColumn(i, tblTotDat);                            
                        }                        
                    }
                    
                    if (tipo ==3)
                    {
                        if(chkMosTuv.isSelected())
                        {
                            objTblMod.removeSystemHiddenColumn(i, tblDat);
                            objTblModTot.removeSystemHiddenColumn(i, tblTotDat);                        

                        }                        
                        else
                        {
                            objTblMod.addSystemHiddenColumn(i, tblDat);
                            objTblModTot.addSystemHiddenColumn(i, tblTotDat);                            
                        }                        
                    } 
                    
                    
                    if (tipo ==4)
                    {
                        if(chkMosFre.isSelected())
                        {
                            objTblMod.removeSystemHiddenColumn(i, tblDat);
                            objTblModTot.removeSystemHiddenColumn(i, tblTotDat);                        

                        }                        
                        else
                        {
                            objTblMod.addSystemHiddenColumn(i, tblDat);
                            objTblModTot.addSystemHiddenColumn(i, tblTotDat);                            
                        }                        
                    }      


                }
           
     }     

    
    
