    private boolean getTipoConfiguracion(){
        boolean blnRes=true;
        String strTipHis="";
        Object objNumMesRep=null;
        Connection conLocGP1;
        Statement stmLocGP1;
        ResultSet rstLocGP1;
        String strSQLGP="";
        try{
            if(  (objTblModHis.isDataModelChanged()) || (objTblModHis02.isDataModelChanged()) || (objTblModHis03.isDataModelChanged()) || (objTblModHis04.isDataModelChanged()) ){
                if(optHisAnu.isSelected()){
                    cargarAnios(0);
                    cargarAnios2(0);
                    cargarAnios3(0);
                    cargarAnios4(0);
                }
                else{
                    cargarAniosMeses(0);
                    cargarAniosMeses2(0);
                    cargarAniosMeses3(0);
                    cargarAniosMeses4(0);
                }
            }
            else{
                conLocGP1=DriverManager.getConnection(objParSis.getStringConexion_Dynamics2021(), objParSis.getUsuarioBaseDatos_Dynamics2021(), objParSis.getClaveBaseDatos_Dynamics2021());
                if(conLocGP1!=null){
                    stmLocGP1=conLocGP1.createStatement();
                    strSQLGP ="";
////                    strSQL+=" SELECT a1.tx_tipHis, a1.ne_numMesRep";
////                    strSQL+=" FROM tbm_filCfgImp AS a1";
                    strSQLGP+=" SELECT cnf.tx_tipHis, cnf.ne_numMesRep \n";
                    strSQLGP+=" FROM Dynamics2021..tbm_filCfgImp as cnf \n";                    
                    strSQLGP+="         INNER JOIN Dynamics2021..tbm_usr  AS usr on (cnf.co_usr = usr.co_usr) \n";                                        
                    strSQLGP+=" WHERE cnf.CO_USR ="+objParSis.getCodigoUsuario() +"";
                    rstLocGP1=stmLocGP1.executeQuery(strSQLGP);
                    if(rstLocGP1.next()){
                        strTipHis=rstLocGP1.getString("tx_tipHis");
                        objNumMesRep=rstLocGP1.getObject("ne_numMesRep");
                        if(strTipHis.equals("A")){
                            optHisAnu.setSelected(true);
                            optHisMen.setSelected(false);
                            //2
                            optHisAnu2.setSelected(true);
                            optHisMen2.setSelected(false);
                            //3
                            optHisAnu3.setSelected(true);
                            optHisMen3.setSelected(false);
                            //4
                            optHisAnu4.setSelected(true);
                            optHisMen4.setSelected(false);
                        }
                        else if(strTipHis.equals("M")){
                            optHisAnu.setSelected(false);
                            optHisMen.setSelected(true);
                            //2
                            optHisAnu2.setSelected(false);
                            optHisMen2.setSelected(true);
                            //3
                            optHisAnu3.setSelected(false);
                            optHisMen3.setSelected(true);
                            //4
                            optHisAnu4.setSelected(false);
                            optHisMen4.setSelected(true);
                        }
                        jspNumMesRep.setValue(objNumMesRep);
                    }

                    conLocGP1.close();
                    conLocGP1=null;
                    stmLocGP1.close();
                    stmLocGP1=null;
                    rstLocGP1.close();
                    rstLocGP1=null;
                    if(optHisAnu.isSelected()){
                        cargarAnios(1);
                        cargarAnios2(1);
                        cargarAnios3(1);
                        cargarAnios4(1);
                    }
                    else {
                        cargarAniosMeses(1);
                        cargarAniosMeses2(1);
                        cargarAniosMeses3(1);
                        cargarAniosMeses4(1);
                    }
                }
            }                
        }
        catch(java.sql.SQLException e){ 
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        catch(Exception e){ 
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }    
    
    
    
