    private boolean eliminaColumnasAdicionadasAnios(){
        boolean blnRes=true;
        try{
            //arlDatPedPre.clear();
            //arlDatDetPedPre.clear();
            objTblMod.removeAllRows();
            objTblModTot.removeAllRows();
            
            for (int i=(objTblMod.getColumnCount()-1); i>=intNumColEstaticas; i--){               
               objTblMod.removeColumn(tblDat, i);
            }
 
            //tengo columnas de mas en la de totales
            for (int i=(objTblModTot.getColumnCount()-1); i>=intNumColEstaticas; i--){               
               objTblModTot.removeColumn(tblTotDat, i);               
            }
        }
        catch(Exception e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }

