    private boolean agregarColumnasPromedioAnual()
    {
        boolean blnRes=true;
        strAux="";
        javax.swing.table.TableColumn tbc;
        ZafTblHeaGrp objTblHeaGrp=(ZafTblHeaGrp)tblDat.getTableHeader();
        objTblHeaGrp.setHeight(16*5);
        ZafTblHeaColGrp objTblHeaColGrp=null;
        intNumColAddProAnu=INT_NUM_CFG_COL_PRO_VEN;//numero de columnas que se adicionan al modelo
        intNumColIniProAnu=intNumColFinTot4;//numero de columnas que tiene el modelo antes de adicionar las columnas
        try
        {
            //14102024_1
            objTblCelRenLblProAnu=new ZafTblCelRenLbl();
            objTblCelRenLblProAnu.setHorizontalAlignment(javax.swing.JLabel.RIGHT);
            objTblCelRenLblProAnu.setTipoFormato(objTblCelRenLblProAnu.INT_FOR_NUM);
            objTblCelRenLblProAnu.setFormatoNumerico(objParSis.getFormatoNumero(),false,true);
            
            objTblCelEdiTxtProAnu=new ZafTblCelEdiTxt();
            
            for (int i=0; i<intNumColAddProAnu; i++){
                //-------------------------------------------------------------------------------------------------------------------
                //15/Mar/2023: Don Luigi solicitó que se le cambie el nombre a la columna "Manual".
                //String strSubTit=(i==0?"Cal1":(i==1?"Cal2":(i==2?"Cal3":(i==3?"Cal4":(i==4?"Máx.Cal.":"Promedio de venta")))));  // JM: newConfig 11/Sept/2023  
                String strSubTit=(i==INT_NUM_COL_PRO_VEN_CAL1?"Cal1":
                                    (i==INT_NUM_COL_PRO_VEN_CAL2?"Cal2":
                                        (i==INT_NUM_COL_PRO_VEN_CAL3?"Cal3":
                                            (i==INT_NUM_COL_PRO_VEN_CAL4?"Cal4":
                                                (i==INT_NUM_COL_PRO_VEN_MAX_CAL?"Máx.Cal.":
                                                    (i==INT_NUM_COL_PRO_VEN_PRO_CAL?"Pro.Cal.":
                                                        (i==INT_NUM_COL_PRO_VEN_MIN_CAL?"Min.Cal.":
                                                            (i==INT_NUM_COL_PRO_VTA_TOT_TEO?"Prom.Vts.Teórico":
                                                                (i==INT_NUM_COL_PRO_VTA_TOT_ANT?"Prom.Vts.Ant.":
                                                                    (i==INT_NUM_COL_PRO_VTA_TOT?"Prom.Vts.Presupuesto":""  )))))))))); // JM: newConfig 11/Sept/2023  
                //-------------------------------------------------------------------------------------------------------------------
                
                tbc=new javax.swing.table.TableColumn(intNumColIniProAnu+i);
                tbc.setHeaderValue("" + strSubTit);
                //Configurar JTable: Establecer el ancho de la columna.
                if (i==INT_NUM_COL_PRO_VTA_TOT || i==INT_NUM_COL_PRO_VTA_TOT_TEO ){ //Promedio de venta presupuesto - Promedio de ventas teorico
                    tbc.setPreferredWidth(120);
                }
                else{
                    tbc.setPreferredWidth(60); //Todas las demas columnas
                }

                //Configurar JTable: Renderizar celdas.
                tbc.setCellRenderer(objTblCelRenLblProAnu);
                tbc.setCellEditor(objTblCelEdiTxtProAnu);
                objTblCelEdiTxtProAnu.addTableEditorListener(new Librerias.ZafTblUti.ZafTblEvt.ZafTableAdapter() {
                    BigDecimal bgdPedCur=new BigDecimal(BigInteger.ZERO);
                    public void beforeEdit(Librerias.ZafTblUti.ZafTblEvt.ZafTableEvent evt) {
                        blnCalTotAftEdi=true;
                    }
                    
                    public void afterEdit(Librerias.ZafTblUti.ZafTblEvt.ZafTableEvent evt) {

                        
                        String strAux=objUti.parseString(objTblMod.getValueAt(tblDat.getSelectedRow(), tblDat.getSelectedColumn()));
                        //Se valida que sólo se calcule 1 vez. Si no se pone ésta validación se calcula 4 veces (1 vez por cada columna que se adicionó al editor).
                        
                        if (blnCalTotAftEdi)
                        {
                            //Si no es un número o es negativo asignar vacío.
                            if (!objUti.isNumero(strAux) || objUti.parseDouble(strAux)<0)
                            {
                                objTblMod.setValueAt("", tblDat.getSelectedRow(), tblDat.getSelectedColumn());
                            }
                            calcularTotalProAnuVenMan();
                            objTblMod.setValueAt("N", tblDat.getSelectedRow(), INT_TBL_DAT_LIN);
                            blnCalTotAftEdi=false;
                        }
                    }
                });     
                

                //Configurar JTable: Agregar la columna al JTable.
                objTblMod.addColumn(tblDat, tbc);

                if(i==0)
                {
                    objTblHeaColGrp=new ZafTblHeaColGrp("Promedio mensual");
                    objTblHeaColGrp.setHeight(16);
                }
                objTblHeaColGrp.add(tbc);
                objTblHeaGrp.addColumnGroup(objTblHeaColGrp);
                
                // --- Ocultar columnas específicas ---
               
                    

                recalcularValoresTabla(tblDat.getSelectedRow());
            }
          
            
            
            
            
            intNumColFinProAnu=objTblMod.getColumnCount();
            objTblHeaGrp=null;
            objTblHeaColGrp=null;
        }
        catch(Exception e)
        {
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }
    
 
    
private void tamanoColumna(javax.swing.JTable tabla, int indiceColumna,int tipo,int tipoTabla) 
{
    if (tipo ==1)
    {
        if (tipoTabla==1)
        {
            tabla.getColumnModel().getColumn(indiceColumna).setMinWidth(0);
            tabla.getColumnModel().getColumn(indiceColumna).setMaxWidth(0);
            tabla.getColumnModel().getColumn(indiceColumna).setPreferredWidth(0);
            tabla.getTableHeader().getColumnModel().getColumn(indiceColumna).setMinWidth(0);
            tabla.getTableHeader().getColumnModel().getColumn(indiceColumna).setMaxWidth(0);            
        }
        else
        {
            tabla.getColumnModel().getColumn(indiceColumna).setMinWidth(0);
            tabla.getColumnModel().getColumn(indiceColumna).setMaxWidth(0);            
        }
       
    }
    else
    {
        TableColumn col = tabla.getColumnModel().getColumn(indiceColumna);
        int anchoActual    = col.getWidth();          // ancho actual
        int anchoPreferido = col.getPreferredWidth(); // ancho preferido
        int anchoMinimo    = col.getMinWidth();       // ancho mínimo
        int anchoMaximo    = col.getMaxWidth();       // ancho máximo  
        if (tipoTabla==1)
        {
            tabla.getColumnModel().getColumn(indiceColumna).setMinWidth(anchoMinimo);
            tabla.getColumnModel().getColumn(indiceColumna).setMaxWidth(anchoMaximo);
            tabla.getColumnModel().getColumn(indiceColumna).setPreferredWidth(anchoPreferido);
            tabla.getTableHeader().getColumnModel().getColumn(indiceColumna).setMinWidth(anchoMinimo);
            tabla.getTableHeader().getColumnModel().getColumn(indiceColumna).setMaxWidth(anchoMaximo);             
        }    
        else
        {
            tabla.getColumnModel().getColumn(indiceColumna).setMinWidth(anchoMinimo);
            tabla.getColumnModel().getColumn(indiceColumna).setMaxWidth(anchoMaximo);            
        }
        
        
        
    }

}    

