private void agregarItemModCol(String item, int fil, int col, BigDecimal valorNue, String nomCol) {

    try {
        String tx_llave = fil + "," + col;
        BigDecimal bgdValorAnt = obtenerTblHist(tx_llave);
        BigDecimal bgdValorNue = valorNue;
        if (bgdValorAnt.compareTo(bgdValorNue) != 0) {
            Items_Historia_Modificados_Imp datos = dataMapHistItem.getOrDefault(
                item,
                new Items_Historia_Modificados_Imp(null, null, null, null, null, null, null, null, null, null, null, null, null, null)
            );

            switch (nomCol.toLowerCase()) {
                case "peso":
                    datos.setNd_pesAct(bgdValorAnt.doubleValue());
                    datos.setNd_pesMod(bgdValorNue.doubleValue());
                    break;

                case "fre.lin.":
                    datos.setNd_freAct(bgdValorAnt.doubleValue());
                    datos.setNd_freMod(bgdValorNue.doubleValue());
                    break;

                case "moq":
                    datos.setNd_moqAct(bgdValorAnt.doubleValue());
                    datos.setNd_moqMod(bgdValorNue.doubleValue());
                    break;

                case "lead time":
                    datos.setNd_leaTimAct(bgdValorAnt.doubleValue());
                    datos.setNd_leaTimMod(bgdValorNue.doubleValue());
                    break;
                    
                case "stock de seguridad":
                    datos.setNd_stobasAct(bgdValorAnt.doubleValue());
                    datos.setNd_stobasMod(bgdValorNue.doubleValue());
                    break;      
                    
                case "fre.cal.itm.":
                    datos.setNd_frefinAct(bgdValorAnt.doubleValue());
                    datos.setNd_frefinMod(bgdValorNue.doubleValue());
                    break;

                case "cob.max.meses":
                    datos.setNd_cobmaxAct(bgdValorAnt.doubleValue());
                    datos.setNd_cobmaxMod(bgdValorNue.doubleValue());
                    break;                    

                default:
                    System.out.println("Columna no reconocida: " + nomCol);
                    break;
            }
            dataMapHistItem.put(item, datos);
            //blnRes = true;
        }

    } catch (Exception e) {
        System.err.println("❌ Error en agregarItemModCol: " + e.getMessage());
    }

    //return blnRes;
}

    
