                queryIni +="FROM(  ";
                queryIni +="            SELECT 1 as co_emp, trim (iv01.ITEMNMBR) as co_itm, 'N' as st_itmstk , trim(iv01.ITEMNMBR) as tx_codalt,trim(iv01.ITMGEDSC) as tx_codalt2, trim (iv01.ITEMDESC) as tx_nomitm, iv01.PRCHSUOM as tx_descor ,   \n";            
                queryIni +="                     iv01.INACTIVE as st_reg,'N' as st_ser, adi.Peso_KG as nd_pesitmkgr,inv.nd_prevta1 as nd_prevta1,trim(iv01.ITEMNMBR) as co_itmmae,(inv.nd_proAnuVenMan ) as nd_proAnuVenMan,    \n";
