                queryIni +="                     (disp.nd_transito ) as  nd_transito,(disp.nd_stockTotal ) as  nd_stockTotal, isnull(inv.co_grpcom,0) as co_grp,isnull(inv.co_detgrpcom,0) as co_detgrp, isnull(inv.co_tipcla,-1) as tipoGrupo ,     \n";
                queryIni +="                     clasi.CodItm, clasi.codAlt, clasi.Linea, clasi.clase, clasi.Marca, clasi.Material, clasi.Peso_KG, clasi.compras, clasi.codLinea, clasi.codClase, clasi.codMarca, clasi.codMaterial, clasi.codPeso, clasi.codCompras     \n ";
                queryIni +="              FROM "+objParSis.getNombreBaseDatosGP()+"..IV00101 as iv01     \n"; 
