            queryIni +="              FROM "+objParSis.getNombreBaseDatosGP()+"..IV00101 as iv01   ";
            queryIni +="                      INNER JOIN Dynamics2021..tbm_inv as inv    on (iv01.ITEMNMBR = inv.tx_itm)   ";
