            queryIni +="                      LEFT JOIN Dynamics2021..view_DIS_IMP_TRANS_EXI_TOTAL as disp   on (iv01.ITEMNMBR = disp.co_itmMae and iv01.ITMSHNAM = disp.codZaf)   \n";
      
            queryIni +="              WHERE   \n";
