            queryIni +="                     iv101.PRCHSUOM as tx_descor ,iv101.INACTIVE as st_reg,'N' as st_ser,   \n";
            queryIni +="                     adi.Peso_KG as nd_pesitmkgr,inv.nd_prevta1 as nd_prevta1,trim(iv101.ITEMNMBR) as co_itmmae, inv.nd_proAnuVenMan as nd_proAnuVenMan,   \n";
            queryIni +="                     isnull(inv.nd_proVenTeo,0) as nd_proVenTeo    \n";
            queryIni +="                     , inv.nd_stkBas, inv.nd_tra, inv.nd_fre, inv.nd_punParMin, inv.nd_punParMax, inv.nd_MOQ, inv.nd_exc,    \n";
            queryIni +="                     0 as nd_canPed1,0 as nd_canpedpes1, 0 as nd_canPed2,0 as nd_canpedpes2    \n";
