            queryIni +="                     , disp.nd_stkAct,disp.nd_stkImp,disp.nd_transito,disp.nd_stockTotal,isnull(inv.co_grpcom,0) as co_grp,isnull(inv.co_detgrpcom,0) as co_detgrp, isnull(inv.co_tipcla,-1) as tipoGrupo,iv101.inactive    \n";            
            queryIni +="              FROM "+objParSis.getNombreBaseDatosGP()+"..IV00101 as iv101   \n";
            queryIni +="                      INNER JOIN Dynamics2021..tbm_inv as inv    on (iv101.ITEMNMBR = inv.tx_itm)   \n";
            queryIni +="                      INNER JOIN "+objParSis.getNombreBaseDatosGP()+"..MSW_vi_datos_adicionales_articulos_1 as adi    on (iv101.ITEMNMBR = adi.ITEMNMBR)    \n";
            queryIni +="                      LEFT JOIN Dynamics2021..view_DIS_IMP_TRANS_EXI_TOTAL as disp   on (iv101.ITEMNMBR = disp.co_itmMae and iv101.ITMSHNAM = disp.codZaf)   \n";
            queryIni +="                      INNER JOIN Dynamics2021..tbl_ItemsClasiAtrib as iv01 on (iv101.ITEMNMBR = iv01.CodItm)   \n";        
            queryIni +="              WHERE   \n";
            queryIni +="                     inv.tx_Codalt2 !=''    \n";             
           // queryIni +="                     iv101.INACTIVE =0    \n";        
            queryIni+="                 " + strFilItm + "";
            queryIni +="                     ) AS g1 \n"; 
