            queryIni +="                     trim(iv011.ITEMNMBR) as tx_codalt,trim(iv011.ITMGEDSC) as tx_codalt2, trim (iv011.ITEMDESC) as tx_nomitm,   \n";
            queryIni +="                     iv011.PRCHSUOM as tx_descor ,iv011.INACTIVE as st_reg,'N' as st_ser,   \n";
            queryIni +="                     adi.Peso_KG as nd_pesitmkgr,inv.nd_prevta1 as nd_prevta1,trim(iv011.ITEMNMBR) as co_itmmae, inv.nd_proAnuVenMan as nd_proAnuVenMan,   \n";
            queryIni +="                     isnull(inv.nd_proVenTeo,0) as nd_proVenTeo    \n";
            queryIni +="                     , inv.nd_stkBas, inv.nd_tra, inv.nd_fre, inv.nd_punParMin, inv.nd_punParMax, inv.nd_MOQ, inv.nd_exc,    \n";
