        queryIni +="        isnull(a1.nd_prevta1,0) as nd_prevta1,isnull(a1.nd_stkAct,0) AS nd_stkAct,isnull(a1.nd_stkImp,0) AS nd_stkImp,isnull(a1.nd_transito,0) AS nd_transito,isnull(a1.nd_stockTotal,0) AS nd_stockTotal,isnull(a1.nd_proAnuVenMan,0) AS nd_proAnuVenMan, \n";
