        queryIni +="                a1.co_grpinv,a1.itemca, \n";
        queryIni +="                sum(isnull(a1.nd_prevtaGLO,0)) as nd_prevta1, \n";
        queryIni +="                sum(isnull(a1.Peso_KG,0)) as Peso_KG \n";
        queryIni +="        FROM (  \n";
