            queryIni +="                (pre.UOMPRICE * 0.75) as nd_prevtaGLO,  \n";
            queryIni +="                isnull (adi.Peso_KG,0) as Peso_KG, \n";
            queryIni +="        FROM dynamics2021..tbm_detGrpInv as det  \n";
