    private boolean calcularTotalesDisponibles(){
        boolean blnRes=true; 
        BigDecimal bgdPesItm=new BigDecimal(0); 
        BigDecimal bgdCosUniGrp=new BigDecimal(BigInteger.ZERO);
        
        
        BigDecimal bgdCanDis=new BigDecimal(0);
        BigDecimal bgdPesItm_CanDis=new BigDecimal(0);
        BigDecimal bgdSum_PesItm_CanDis=new BigDecimal(0);
        
        BigDecimal bgdSum_CosUni_CanDis=new BigDecimal(0);
        
        try{
            for(int i=0; i<objTblMod.getRowCountTrue(); i++){
                bgdPesItm=new BigDecimal(objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG)==null?"0":(objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG).toString().equals("")?"0": objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG).toString()));
////                bgdCanDis =new BigDecimal(objTblMod.getValueAt(i, intNumColIniStk+INT_NUM_COL_STK_TOT_DIS));
                bgdCanDis=new BigDecimal(objTblMod.getValueAt(i, intNumColIniStk+INT_NUM_COL_STK_TOT_DIS)==null?"0":(objTblMod.getValueAt(i, intNumColIniStk+INT_NUM_COL_STK_TOT_DIS).toString().equals("")?"0":objTblMod.getValueAt(i, intNumColIniStk+INT_NUM_COL_STK_TOT_DIS).toString()));
                // Convertir a 0 si el valor es equivalente a 0E-10
                
                bgdCosUniGrp=new BigDecimal(objTblModFix.getValueAt(i, INT_TBL_DAT_FIX_COS_UNI_GRP)==null?"0":(objTblModFix.getValueAt(i, INT_TBL_DAT_FIX_COS_UNI_GRP).toString().equals("")?"0":objTblModFix.getValueAt(i, INT_TBL_DAT_FIX_COS_UNI_GRP).toString()));
                
                if(chkMosDatKil.isSelected())
                {    
                    if((bgdPesItm.compareTo(BigDecimal.ZERO)!=0) && (bgdCanDis.compareTo(BigDecimal.ZERO)!=0))
                         bgdSum_CosUni_CanDis=bgdSum_CosUni_CanDis.add(((bgdCanDis.divide(bgdPesItm, objParSis.getDecimalesMostrar(), BigDecimal.ROUND_HALF_UP)).multiply(bgdCosUniGrp)));  
                    else
                        bgdSum_CosUni_CanDis=bgdSum_CosUni_CanDis;
                }
                else
                {
                    bgdSum_CosUni_CanDis=bgdSum_CosUni_CanDis.add(((bgdCanDis).multiply(bgdCosUniGrp)));
                } 
                 //bgdSum_PesItm_CanDis=bgdSum_PesItm_CanDis.add(bgdPesItm_CanDis);
          
           
                bgdCanDis=new BigDecimal(0);
                bgdPesItm_CanDis=new BigDecimal(0);
                
                bgdPesItm=new BigDecimal(0);
          
            }
                  

            objTblModTot.setValueAt("" + objUti.redondearBigDecimal(bgdSum_CosUni_CanDis, objParSis.getDecimalesMostrar()), 1, intNumColIniStk+INT_NUM_COL_STK_TOT_DIS);//columna de Stock Actual
            bgdSum_CosUni_CanDis=new BigDecimal(0);
            
            
             
        }
        catch(Exception e){
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }
    
