   private boolean cargarDetallePedidosConfigurados_SQL_1(HashMap<String, PedidosDetEmbarc> dataMapConsulta){
        boolean blnRes=true;
        Statement stmCanPedEmb;
////        String strFilItm="";
        try{
            if(conGP!=null){
                stmGP=conGP.createStatement();
                
////                if (objVenConItm01GP.isCondicionAplicada())
////                {
////                    strFilItm+=objVenConItm01GP.getCondicionesSQL();
////                }
               
                //crear un arreglo y colocar ahi la informacion para luego ser leida antes de terminar de hacer la consulta.
                strSQL="";
                    if (objVenConItm01GP.ValidaAtributos())//con atributo
                    {                
                        if (chkMosCabec.isSelected())//con cabecera
                        {                        
                            strSQL+="SELECT pednot.pedido,pednot.co_emp,pednot.co_loc,pednot.orden,pednot.co_tipdoc ,pednot.fe_arr,pednot.item,pednot.nd_Can \n";
                            strSQL+="       ,isnull(det.co_grpInv,0) as co_grpInv  ,det.tx_itmPad,inv.co_grpcom,inv.co_detgrpcom \n";   
                            strSQL+="FROM view_det_pedi_not  as pednot\n";   
                            strSQL+="     INNER JOIN tbm_inv as inv on (pednot.item = inv.tx_itm) ";
                            strSQL+="     LEFT JOIN (";
                            strSQL+="                SELECT det.tx_codItm,cab.co_grpInv,cab.tx_itmPad ";
                            strSQL+="                FROM tbm_detGrpInv as det"; 
                            strSQL+="                   INNER JOIN tbm_cabGrpInv as  cab on (det.co_grpInv = cab.co_grpInv) ";                            
                            strSQL+="                WHERE cab.co_tipAgr =2";
                            strSQL+="                ) as det (pednot.item = det.tx_codItm)";   
                            strSQL+="WHERE   pednot.item in (   " + strFilItmGolbal2 + ")";   
                            
                        }
                    }
                    else
                    {
                        
                    }    
                    //aqui
                            
                if (!chkMosCabec.isSelected())// SIN AGRUPACION
                {
                    strSQL+="SELECT ped.co_emp, ped.co_loc, ped.co_tipDoc, ped.orden, ped.item,ped.nd_can,ped.codalt \n";
                    strSQL+="FROM view_det_pedi_not AS ped \n";                
                     if (!objVenConItm01GP.ValidaAtributos())//SIN ATRIBUTOS
                            strSQL+="    INNER JOIN "+ objParSis.getNombreBaseDatosGP()  +"..iv00101 AS iv01  ON (ped.item = iv01.ITEMNMBR)   \n";          
                     else//CON ATRIBUTOS
                            strSQL+="    INNER JOIN dynamics2021..tbl_ItemsClasiAtrib AS iv01  ON (ped.item = iv01.CodItm)  \n";        
                    strSQL+="WHERE  ped.co_tipdoc !=0 \n";                
                    strSQL+="       " + strFilItmGolbal + "";                    
                }
                else//CON AGRUPACION
                {
                    strSQL+="SELECT 0 AS co_emp, 1 as co_loc,a1.co_tipDoc as co_tipdoc, a1.orden, a1.itemcab as item,  \n";
                    strSQL+="       SUM(a1.nd_can) as nd_can , a1.itemcab as codalt \n"; 
                    strSQL+="FROM (\n"; 
                    
                    strSQL+="       SELECT DISTINCT ped.co_emp, ped.co_loc, ped.co_tipDoc, ped.orden, ped.item,ped.nd_can,ped.codalt,  \n";
                    strSQL+="                       excl.co_grpInv,  excl.co_grpcom, excl.co_detgrpcom, \n"; 
                    strSQL+="                       (case when isnull(excl.co_grpInv,0) =0 then item else cabgrpinv.tx_itmPad end) as itemcab\n"; 
                    strSQL+="       FROM view_det_pedi_not AS ped \n";
                    if (!objVenConItm01GP.ValidaAtributos())//SIN ATRIBUTOS
                        strSQL+="       INNER JOIN "+objParSis.getNombreBaseDatosGP()+"..iv00101 AS iv01  ON (ped.item = iv01.ITEMNMBR) \n";
                    else//CON ATRIBUTOS
                        strSQL+="       INNER JOIN Dynamics2021..tbl_ItemsClasiAtrib as iv01 on (ped.item  = iv01.CodItm)   \n";
                    strSQL+="           LEFT JOIN  ( \n"; 
                    strSQL+="                       SELECT det.tx_coditm , cab.co_grpinv, inv.co_grpcom, inv.co_detgrpcom \n";
                    strSQL+="                       FROM dynamics2021..tbm_detGrpInv AS det  \n"; 
                    strSQL+="                           INNER JOIN dynamics2021..tbm_cabGrpInv AS cab ON (det.co_grpinv = cab.co_grpinv)   \n";
                     if (!objVenConItm01GP.ValidaAtributos())//SIN ATRIBUTOS
                     {
                         strSQL+="                           INNER JOIN "+objParSis.getNombreBaseDatosGP()+"..IV00101 AS iv01 ON (det.tx_codItm = iv01.ITEMNMBR)    \n";
                         strSQL+="                           INNER JOIN Dynamics2021..tbm_inv AS inv ON (det.tx_codItm = inv.tx_itm)   \n";
                         //181112024strSQL+="                  WHERE iv01.inactive = 0  \n"; 
                         strSQL+="                  WHERE inv.tx_codalt2 !=''  \n"; 
                     }
                     else//CON ATRIBUTOS
                     {
                         strSQL+="                           INNER JOIN "+objParSis.getNombreBaseDatosGP()+"..IV00101 AS iv101 ON (det.tx_codItm = iv101.ITEMNMBR)    \n"; 
                         strSQL+="                           INNER JOIN Dynamics2021..tbm_inv AS inv ON (det.tx_codItm = inv.tx_itm)   \n";
                         strSQL+="                           INNER JOIN Dynamics2021..tbl_ItemsClasiAtrib as iv01 on (iv101.ITEMNMBR = iv01.CodItm)   \n";
                         //181112024strSQL+="                  WHERE iv101.inactive = 0  \n"; 
                         strSQL+="                  WHERE inv.tx_codalt2 !=''  \n"; 
                         
                     }
                     
                     strSQL+="                          " + strFilItmGolbal + " \n";
                     strSQL+="                          AND cab.co_tipAgr = "+co_tipAgrGlobal+" /*AND cab.st_reg = 'A'*/  \n";
                     strSQL+="                    ) AS excl ON ped.item = excl.tx_coditm  \n";
                     strSQL+="           LEFT JOIN  dynamics2021..tbm_cabGrpInv  as cabgrpinv on (excl.co_grpInv = cabgrpinv.co_grpInv) \n";    
                     strSQL+="           WHERE ped.co_tipdoc !=0  \n";
                     strSQL+="                 " + strFilItmGolbal + " \n";
                     strSQL+="           ) AS a1  \n";
                     strSQL+="           GROUP BY a1.co_grpInv, a1.itemcab, a1.co_tipDoc, a1.orden  \n";
                     
                     
                }
                
                
                
                rstGP=stmGP.executeQuery(strSQL);
                arlDatDetPedEmb.clear();
                String cadena="";
                while(rstGP.next()){
                    cadena="";
                    arlRegDetPedEmb=new ArrayList();
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_EMP, rstGP.getString("co_emp"));
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_LOC, rstGP.getString("co_loc"));
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_TIP_DOC, rstGP.getInt("co_tipDoc"));
                    //arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_DOC, rstCanPedEmb.getString("co_doc"));//MOD
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_DOC, rstGP.getString("orden"));
                    //arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_ITM, rstCanPedEmb.getString("co_itm"));//mod
                        arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_ITM, rstGP.getString("item"));
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_CAN_PED_EMB, rstGP.getString("nd_can"));
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_COD_ALT_ITM, rstGP.getString("codAlt"));
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_EST, "");
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_NUM_COL, "0"); 
                    arlRegDetPedEmb.add(INT_ARL_DET_PED_EMB_GP,  rstGP.getString("item")); 
                    arlDatDetPedEmb.add(arlRegDetPedEmb); 
                    cadena =rstGP.getString("co_tipDoc") +";"+rstGP.getString("orden")+";" +rstGP.getString("item");
                    dataMapConsulta.put(cadena, new PedidosDetEmbarc (  rstGP.getString("orden"), rstGP.getInt("co_tipDoc"),rstGP.getString("item"),rstGP.getDouble("nd_can"),"N",0));  //14102024   
                    
                    
                    
                }
                stmGP.close();
                stmGP=null;
                rstGP.close();
                rstGP=null;
                
                //se cargan los datos de valores del pedido embarcado
                int intCodEmpNomPedEmb=-1;
                int intCodLocNomPedEmb=-1;
                int intCodTipDocNomPedEmb=-1;
                String intCodDocNomPedEmb="";
                int intNumColNomPedEmb=-1;                
                int intCodEmpCanPedEmb=-1;
                int intCodLocCanPedEmb=-1;
                int intCodTipDocCanPedEmb=-1;
                String intCodDocCanPedEmb="";                
                String strEstPedEmb="";
                String strItem="",cadena1="";
                
                for(int d=0; d<(arlDatPedEmb.size()); d++){
                    intCodEmpNomPedEmb=objUti.getIntValueAt(arlDatPedEmb, d, INT_ARL_PED_EMB_COD_EMP);
                    intCodLocNomPedEmb=objUti.getIntValueAt(arlDatPedEmb, d, INT_ARL_PED_EMB_COD_LOC);
                    intCodTipDocNomPedEmb=objUti.getIntValueAt(arlDatPedEmb, d, INT_ARL_PED_EMB_COD_TIP_DOC);
                    intCodDocNomPedEmb=objUti.getStringValueAt(arlDatPedEmb, d, INT_ARL_PED_EMB_COD_DOC);
                    intNumColNomPedEmb=objUti.getIntValueAt(arlDatPedEmb, d, INT_ARL_PED_EMB_NUM_COL);
                    
                    
                    for(int e=0; e<(arlDatDetPedEmb.size()); e++){
                        cadena1="";
                        intCodEmpCanPedEmb=objUti.getIntValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_EMP);
                        intCodLocCanPedEmb=objUti.getIntValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_LOC);
                        intCodTipDocCanPedEmb=objUti.getIntValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_TIP_DOC);
                        intCodDocCanPedEmb=objUti.getStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_DOC);
                        strItem =objUti.getStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_ITM);
                        cadena1=objUti.getStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_TIP_DOC)+";"+ objUti.getStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_COD_DOC)+";"+strItem;
                        
                    PedidosDetEmbarc objCommPedidosDetEmbarc = dataMapConsulta.get(cadena1);
                    if (objCommPedidosDetEmbarc != null) 
                    {
                        if ((intCodTipDocNomPedEmb ==objCommPedidosDetEmbarc.getNe_tipDoc())  && (intCodDocNomPedEmb.equals(objCommPedidosDetEmbarc.getSt_Orden())))
                         {
                             objCommPedidosDetEmbarc.setEstado("S");
                         }   
                    }                        
                        
                        
                       //14102024
                        strEstPedEmb=objUti.getStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_EST);
                        if(strEstPedEmb.equals("")){
                            if( (intCodEmpNomPedEmb==intCodEmpCanPedEmb) && (intCodLocNomPedEmb==intCodLocCanPedEmb) && (intCodTipDocNomPedEmb==intCodTipDocCanPedEmb) && (intCodDocNomPedEmb.equals(intCodDocCanPedEmb)) ){
                                objUti.setStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_EST, "S");
                                objUti.setStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_NUM_COL, ""+intNumColNomPedEmb);
                            }
                        }
                    }                    
                }                
                
                //SE BLANQUEAN LOS ESTADOS DE LOS REGISTROS PARA PODER PROCESARLOS AL MOMENTO DE CARGAR LOS DATOS
                for(int e=0; e<(arlDatDetPedEmb.size()); e++){
                    objUti.setStringValueAt(arlDatDetPedEmb, e, INT_ARL_DET_PED_EMB_EST, "");   
                }
            }
        }
        catch(java.sql.SQLException e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        catch(Exception e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }       
    
