    private boolean isCamVal(){
        int intArlColSel;
        String strColModLib="";

        //Valida que existan NPP antes de guardar
        if(arlDatPedPre.size()>0){ /* Se añade ese nombre al arreglo q contiene la informacion de los Pedidos Previos*/
            for(int i=0; i<arlDatPedPre.size();i++){
                intArlColSel=objUti.getIntValueAt(arlDatPedPre, i, INT_ARL_CAB_PED_PRE_NUM_COL);
                strColModLib=objUti.getStringValueAt(arlDatPedPre, i, INT_ARL_CAB_PED_PRE_COL_MOD);
                if(intArlColSel==(intNumColFinPedPre-2)){
                    if(strColModLib.equals("I")){
                        if(strNomPedPreIngLSC.equals("")){  
                            strNomPedPreIngLSC="";
                            /* Valida si se debe seleccionar o digitar el Número del Pedido.*/
                            if(objParSis.getCodigoMenu()==objZafImp.INT_COD_MNU_PRG_CFG_COM_LOC) {  //Compras Locales
                                //Se digita el número del pedido, debido a que no se crearán NPP de Compras Locales en el Presupuesto.
                                strNomPedPreIngLSC= (javax.swing.JOptionPane.showInputDialog(javax.swing.JOptionPane.getFrameForComponent(tblDat), "Ingrese el nombre del Pedido Previo:", "Mensaje del sistema Zafiro", javax.swing.JOptionPane.QUESTION_MESSAGE)).toString();
                                if(strNomPedPreIngLSC != null) { //Aceptar
                                    objUti.setStringValueAt(arlDatPedPre, i, INT_ARL_CAB_PED_PRE_NUM_PED_PRE, strNomPedPreIngLSC);
                                    BLN_EXI_NPP=true;    
                                }
                                else{ //Cancelar
                                    strNomPedPreIngLSC="";
                                    return false;
                                }
                            }
                            else{ //Importaciones
                                //Se selecciona el número del pedido, debido a que las NPP de Importaciones, se crearán en el Presupuesto.
                                Compras.ZafCom112.ZafCom112_03 objPed=new Compras.ZafCom112.ZafCom112_03(javax.swing.JOptionPane.getFrameForComponent(this), true, objParSis);
                                objPed.setVisible(true);
                                if(objPed.isPedSel()) { //Aceptar
                                    strNomPedPreIngLSC=objPed.getNumPedSel(); 
                                    objUti.setStringValueAt(arlDatPedPre, i, INT_ARL_CAB_PED_PRE_NUM_PED_PRE, strNomPedPreIngLSC);
                                    BLN_EXI_NPP=true;                                
                                }
                                else{ //Cancelar
                                    strNomPedPreIngLSC=""; 
                                    return false;
                                }
                                objPed=null;                            
                            }
                        }
                        break;
                    }
                }
            }        
        }  
        else{
            //Cuando no existe NPP
            return false;
        }
        return true;
    } 
    
    private boolean guardarDatos(){
        boolean blnRes=false;
        try{
            conGP=DriverManager.getConnection(objParSis.getStringConexion_Dynamics2021(), objParSis.getUsuarioBaseDatos_Dynamics2021(), objParSis.getClaveBaseDatos_Dynamics2021());
            if(conGP!=null)   
            {
                conGP.setAutoCommit(false);
                if(elimina_tbm_filCfgImp())
                {
                    if(inserta_tbm_filCfgImp())
                    {
                        if(elimina_tbm_filAniSelCfgImp())
                        {
                            if(inserta_tbm_filAniSelCfgImp())
                            {
                                if(elimina_tbm_filMesSelCfgImp())
                                {
                                    if(inserta_tbm_filMesSelCfgImp())
                                    {
                                        if(update_tbmInv())
                                        {
                                            if (update_tbh_hiscamImp())
                                            {
                                                conGP.commit();
    //------------------------------------------------------------------------------
                                                objTblMod.initRowsState();
                                                objTblMod.setDataModelChanged(false);
                                                objTblModFix.initRowsState();
                                                objTblModFix.setDataModelChanged(false);
    //------------------------------------------------------------------------------
                                                blnRes=true;                                                
                                                
                                            }
                                            
                                            

                                        }
                                        else
                                            con.rollback();
                                    }
                                    else
                                        con.rollback();
                                }
                                else
                                    con.rollback();
                            }
                            else
                                conGP.rollback();
                        }
                        else
                            conGP.rollback();
                    }
                    else
                        conGP.rollback();
                }
                else
                    conGP.rollback();
            conGP.close();
            conGP=null;
            }
        }
        catch(java.sql.SQLException e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        catch(Exception e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }
    
private boolean update_tbh_hiscamImp() {
    boolean blnRes = false;
    String sql="";
    try 
    {
        if(conGP!=null)
        {   
            stmGP=conGP.createStatement();
            if (dataMapHistItem != null && !dataMapHistItem.isEmpty()) 
            {
                for (Map.Entry<String, Items_Historia_Modificados_Imp> entry : dataMapHistItem.entrySet()) 
                {
                    String item = entry.getKey(); // clave → código del ítem
                    Items_Historia_Modificados_Imp datos = entry.getValue(); // objeto con los valores modificados
                     sql += "\n INSERT INTO tbh_hiscamImp (" +
                                 "tx_itm, nd_pesAct, nd_pesMod, nd_freAct, nd_freMod, nd_moqAct, nd_moqMod, " +
                                 "nd_leaTimAct, nd_leaTimMod, nd_frefinAct, nd_frefinMod, nd_stosegAct, nd_stosegMod, " +
                                 "tx_usring, fe_ing, tx_maq, co_mnu) VALUES ('" + item + "', "+ datos.getNd_pesAct() +", "+ datos.getNd_pesMod() +", "+datos.getNd_freAct() +", "
                                 + ""+datos.getNd_freMod() +", "+ datos.getNd_moqAct() +", "+ datos.getNd_moqMod() +", "+ datos.getNd_leaTimAct() +" , "+ datos.getNd_leaTimMod() +","
                                 + ""+ datos.getNd_frefinAct() +" , "+ datos.getNd_frefinMod() +","+ datos.getNd_stobasAct() +" , "+ datos.getNd_stobasMod() +", '"+ objParSis.getNombreUsuario() +"', GETDATE(),"
                                 + " '"+objParSis.getNombreComputadora() +"', "+objParSis.getCodigoMenu()+") ;\n";
                    

                    blnRes = true; // Si hubo datos, marcamos como exitoso
                }
            }
            if (blnRes)
                stmGP.executeUpdate(sql);
                    stmGP.close();
                    stmGP=null;            
        }        
    }
    catch(java.sql.SQLException e){
        objUti.mostrarMsgErr_F1(this, e);
        blnRes=false;
    }
    catch(Exception e){
        objUti.mostrarMsgErr_F1(this, e);
        blnRes=false;
    }    
    return blnRes;
}

    
