    private boolean setValSumatoriaSSLTFC()//ssltfc
    {  
        boolean blnRes=true;
        
        BigDecimal bgdStkTotSSLTFC=BigDecimal.ZERO;    
        
        
        BigDecimal bgdFrecuencia=BigDecimal.ZERO;  
        BigDecimal bgdStockBase=BigDecimal.ZERO; 
        BigDecimal bgdTransito=BigDecimal.ZERO; 
        
        
        try{
            for(int i=0; i<objTblMod.getRowCountTrue(); i++)
            {
                bgdFrecuencia= new BigDecimal(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_TBL_DAT_ADI_ITM_FRE_CAL_LIN))==null?"0":(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_TBL_DAT_ADI_ITM_FRE_CAL_LIN)).toString().equals("")?"0":objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_TBL_DAT_ADI_ITM_FRE_CAL_LIN)).toString()))    ;//Frecuencia 
                bgdStockBase= new BigDecimal(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS))==null?"0":(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS)).toString().equals("")?"0":objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS)).toString()))    ;//Stock Base 
                bgdTransito= new BigDecimal(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA))==null?"0":(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA)).toString().equals("")?"0":objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA)).toString()))    ;//Stock Base 
                
                bgdStkTotSSLTFC = bgdFrecuencia.add(bgdTransito).add(bgdStockBase); 
                
                objTblMod.setValueAt(""+bgdStkTotSSLTFC, i, (intNumColIniValManCalRep + INT_TBL_DAT_ADI_ITM_SUM));
            }            
        }
        catch(Exception e)
        {
            objUti.mostrarMsgErr_F1(null, e);
            blnRes=false;
        }
        return blnRes;
    }  
    
