            bgdFrecuencia= new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE))==null?"0":(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE)).toString().equals("")?"0":objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE)).toString()))    ;//Frecuencia 
            bgdStockBase= new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS))==null?"0":(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS)).toString().equals("")?"0":objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_STK_BAS)).toString()))    ;//Stock Base 
            bgdTransito= new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA))==null?"0":(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA)).toString().equals("")?"0":objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_TRA)).toString()))    ;//Stock Base 
