//                bgdPPMax=new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniValManCalRep + INT_NUM_DAT_ADI_ITM_PUN_PAR_MAX))==null?"0":(objTblMod.getValueAt(fila, (intNumColIniValManCalRep + INT_NUM_DAT_ADI_ITM_PUN_PAR_MAX)).toString().equals("")?"0":objTblMod.getValueAt(fila, (intNumColIniValManCalRep + INT_NUM_DAT_ADI_ITM_PUN_PAR_MAX)).toString()))    ;//PPMax
                 

