    private boolean setValFrecuenciaItem(){  //AZ
        boolean blnRes=true;
        BigDecimal bgdPromVtaTOTAnual; 
        BigDecimal bgdMOQ; 
        BigDecimal bgdFrecuenciaItm; 
        try{
            for(int i=0; i<objTblMod.getRowCountTrue(); i++){                

                bgdMOQ = BigDecimal.ZERO; 
                bgdMOQ = new BigDecimal(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ))==null?"0":(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ)).toString().equals("")?"0":objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ)).toString()));

                bgdPromVtaTOTAnual = BigDecimal.ZERO; //El valor minimo del promedio de venta debe ser 1 para evitar error al momento de dividir. 
                bgdPromVtaTOTAnual = new BigDecimal(objTblMod.getValueAt(i, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT))==null?"1":(objTblMod.getValueAt(i, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT)).toString().equals("")?"1":objTblMod.getValueAt(i, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT)).toString()));
                if ((bgdPromVtaTOTAnual.compareTo(BigDecimal.ZERO)==0) || (bgdMOQ.compareTo(BigDecimal.ZERO)==0))
                    objTblMod.setValueAt(BigDecimal.ONE, i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE_CAL));  //Frecuencia ITEM Calculada
                else
                {
                    bgdFrecuenciaItm=bgdMOQ.divide(bgdPromVtaTOTAnual, 0, BigDecimal.ROUND_UP);  //Siempre redondea para arriba
                    objTblMod.setValueAt(bgdFrecuenciaItm, i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE_CAL));  //Frecuencia ITEM Calculada                       
                }    
                    
//                bgdPromVtaTOTAnual = (bgdPromVtaTOTAnual.compareTo(BigDecimal.ZERO)==0? BigDecimal.ONE:bgdPromVtaTOTAnual);
                



            }
        }
        catch(Exception e){
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }  
    
private boolean setValFrecuenciaItem(int fila){  //AZ
        boolean blnRes=true;
        BigDecimal bgdPromVtaTOTAnual; 
        BigDecimal bgdMOQ; 
        BigDecimal bgdFrecuenciaItm; 
        try{
               

                bgdMOQ = BigDecimal.ZERO; 
                bgdMOQ = new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ))==null?"0":(objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ)).toString().equals("")?"0":objTblMod.getValueAt(fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_MOQ)).toString()));

                bgdPromVtaTOTAnual = BigDecimal.ZERO; //El valor minimo del promedio de venta debe ser 1 para evitar error al momento de dividir. 
                bgdPromVtaTOTAnual = new BigDecimal(objTblMod.getValueAt(fila, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT))==null?"1":(objTblMod.getValueAt(fila, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT)).toString().equals("")?"1":objTblMod.getValueAt(fila, (intNumColIniProAnu+INT_NUM_COL_PRO_VTA_TOT)).toString()));
                if ((bgdPromVtaTOTAnual.compareTo(BigDecimal.ZERO)==0) || (bgdMOQ.compareTo(BigDecimal.ZERO)==0))
                    objTblMod.setValueAt(BigDecimal.ONE, fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE_CAL));  //Frecuencia ITEM Calculada
                else
                {
                    bgdFrecuenciaItm=bgdMOQ.divide(bgdPromVtaTOTAnual, 0, BigDecimal.ROUND_UP);  //Siempre redondea para arriba
                    objTblMod.setValueAt(bgdFrecuenciaItm, fila, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE_CAL));  //Frecuencia ITEM Calculada                       
                }    
                    

        }
        catch(Exception e){
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }         
    
    
    
    /**
     * Calculo de frecuiencia del item por linea, pedido? 
     * @return 
     */
    private boolean setValFrecuenciaLinea(){  //JM 15/Dic/2023 
        boolean blnRes=true;
        int intFrecuenciaLinea, intFrecuenciaItem;
        double dblPesoTotal=0.00, dblValorTotal=0.00, dblFrecuencia=0.00;
        try{
            dblPesoTotal = Double.parseDouble( objTblModTot.getValueAt(0, (intNumColFinProAnu-1)).toString() ) ;
            dblValorTotal = Double.parseDouble( objTblModTot.getValueAt(1, (intNumColFinProAnu-1)).toString() ) ;
             
            if(strTipoSeleccion.length()>0){
                if(strTipoSeleccion.equals("Peso")){
                    dblFrecuencia = dblValorMOQ_linea / dblPesoTotal ;
                }
                else{
                    dblFrecuencia = dblValorMOQ_linea / dblValorTotal ;
                }
            }
//            System.out.println("dblFrecuencia  " + dblFrecuencia);
            // Redondear hacia arriba
            intFrecuenciaLinea = (int) Math.ceil(dblFrecuencia);
//            System.out.println("dblFrecuencia Linea  " + intFrecuenciaLinea);
            for(int i=0; i<objTblMod.getRowCountTrue(); i++){                
                objTblMod.setValueAt(intFrecuenciaLinea, i, (intNumColIniValManCalRep+INT_TBL_DAT_ADI_ITM_FRE_CAL_LIN));  //Frecuencia ITEM Calculada
                intFrecuenciaItem = (int) Math.ceil( Double.parseDouble(objTblMod.getValueAt(i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE_CAL)).toString())  ) ;
//                System.out.println("intFrecuenciaItem " + intFrecuenciaItem);
                if(intFrecuenciaItem>=intFrecuenciaLinea){
                    objTblMod.setValueAt(intFrecuenciaItem, i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE));  //Frecuencia ITEM Calculada
                }
                else{
                    objTblMod.setValueAt(intFrecuenciaLinea, i, (intNumColIniValManCalRep+INT_NUM_DAT_ADI_ITM_FRE));  //Frecuencia ITEM Calculada
                }
            } 
        }
        catch(Exception e){
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }    
    
    
    
