    /**
     * JM Solicitado por LSC, Ocultar columnas de las notas de pedido previas 
     * 
     * @return 
     */
    private boolean ocultaColumnasNotasPedidoPrevias(){
        boolean blnRes=true;
        try{
            // Ocultar 
            for(int i=intNumColIniPedPre; i<(intNumColFinPedPre); i++){
                objTblMod.addSystemHiddenColumn(i, tblDat);
                objTblModTot.addSystemHiddenColumn(i, tblTotDat);
            }
        }
        catch(Exception e){
            objUti.mostrarMsgErr_F1(this, e);
            blnRes=false;
        }
        return blnRes;
    }
    
