            bgdPes=new BigDecimal(objTblMod.getValueAt(fila, INT_TBL_DAT_PES_KG)==null?"0":(objTblMod.getValueAt(fila, INT_TBL_DAT_PES_KG).toString().equals("")?"0":objTblMod.getValueAt(fila, INT_TBL_DAT_PES_KG).toString()));
            //Totales 1
