    private boolean calcularTotalPromedioAnualCalculada_peso_calMax(){
        boolean blnRes=true;
        BigDecimal bgdCanRepCalMax=new BigDecimal(0);
        BigDecimal bgdSum_PesItm_CanRepCalMax=new BigDecimal(0);
        BigDecimal bgdPesItm=new BigDecimal(0);//peso
        BigDecimal bgdPesItm_CanRepCal=new BigDecimal(0);//peso
        
        // JM 19/Dic/2023  
        BigDecimal bgdProCalCalMax=new BigDecimal(0);
        BigDecimal bgdPesItm_ProCal=new BigDecimal(0); 
        BigDecimal bgdSum_PesItm_ProCal=new BigDecimal(0);
        
        BigDecimal bgdMinCalCalMax=new BigDecimal(0);
        BigDecimal bgdPesItm_MinCal=new BigDecimal(0); 
        BigDecimal bgdSum_PesItm_MinCal=new BigDecimal(0);
        // JM 19/Dic/2023  
        
        try{
            for(int i=0; i<objTblMod.getRowCountTrue(); i++){
                bgdCanRepCalMax=new BigDecimal(objTblMod.getValueAt(i, (intNumColIniProAnu+4))==null?"0":(objTblMod.getValueAt(i, (intNumColIniProAnu+4)).toString().equals("")?"0": objTblMod.getValueAt(i, (intNumColIniProAnu+4)).toString()));
                bgdPesItm=new BigDecimal(objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG)==null?"0":(objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG).toString().equals("")?"0":objTblMod.getValueAt(i, INT_TBL_DAT_PES_KG).toString()));
                /* JM 19/Dic/2023  */
                bgdProCalCalMax=new BigDecimal(objTblMod.getValueAt(i, (intNumColIniProAnu+5))==null?"0":(objTblMod.getValueAt(i, (intNumColIniProAnu+5)).toString().equals("")?"0": objTblMod.getValueAt(i, (intNumColIniProAnu+5)).toString()));
                bgdMinCalCalMax=new BigDecimal(objTblMod.getValueAt(i, (intNumColIniProAnu+6))==null?"0":(objTblMod.getValueAt(i, (intNumColIniProAnu+6)).toString().equals("")?"0": objTblMod.getValueAt(i, (intNumColIniProAnu+6)).toString()));
                /* JM 19/Dic/2023  */
                
                
                
                        if ((strValidaSelTipo.equals("PESO")) || (chkMosDatKil.isSelected()))
                        {
                                bgdPesItm_CanRepCal=bgdCanRepCalMax;//No se multiplica por el peso, porque la información de las columnas de la tabla de detalle ya esta en kilos, por tanto es sólo de sumar
                                 /* JM 19/Dic/2023  */
                                bgdPesItm_ProCal=bgdProCalCalMax;
                                bgdPesItm_MinCal=bgdMinCalCalMax;
                                 /* JM 19/Dic/2023  */                    
                        }
                        else
                        {

                            if(chkMosDatKil.isSelected()){
                                bgdPesItm_CanRepCal=bgdCanRepCalMax;//No se multiplica por el peso, porque la información de las columnas de la tabla de detalle ya esta en kilos, por tanto es sólo de sumar
                                 /* JM 19/Dic/2023  */
                                bgdPesItm_ProCal=bgdProCalCalMax;
                                bgdPesItm_MinCal=bgdMinCalCalMax;
                                 /* JM 19/Dic/2023  */
                            }
                            else{
                                bgdPesItm_CanRepCal=bgdCanRepCalMax.multiply(bgdPesItm);
                                 /* JM 19/Dic/2023  */
                                bgdPesItm_ProCal=bgdProCalCalMax.multiply(bgdPesItm);
                                bgdPesItm_MinCal=bgdMinCalCalMax.multiply(bgdPesItm);
                                 /* JM 19/Dic/2023  */
                            }                            
                        }    
                
                    
                bgdSum_PesItm_CanRepCalMax=bgdSum_PesItm_CanRepCalMax.add(bgdPesItm_CanRepCal);
                /* JM 19/Dic/2023  */
                bgdSum_PesItm_ProCal=bgdSum_PesItm_ProCal.add(bgdPesItm_ProCal);
                bgdSum_PesItm_MinCal=bgdSum_PesItm_MinCal.add(bgdPesItm_MinCal);
                /* JM 19/Dic/2023  */
                
                bgdCanRepCalMax=new BigDecimal(0);
                bgdPesItm=new BigDecimal(0);
                bgdPesItm_CanRepCal=new BigDecimal(0);
                
                bgdCanRepCalMax=new BigDecimal(0);
                bgdPesItm_CanRepCal=new BigDecimal(0);
                
                bgdCanRepCalMax=new BigDecimal(0);
                bgdPesItm_CanRepCal=new BigDecimal(0);
            }
            objTblModTot.setValueAt("" + objUti.redondearBigDecimal(bgdSum_PesItm_CanRepCalMax, objParSis.getDecimalesMostrar()), 0, (intNumColIniProAnu+4));//columna de promedio anual calculado
            /* JM 19/Dic/2023  */
            objTblModTot.setValueAt("" + objUti.redondearBigDecimal(bgdSum_PesItm_ProCal, objParSis.getDecimalesMostrar()), 0, (intNumColIniProAnu+5));//columna de promedio anual calculado
            objTblModTot.setValueAt("" + objUti.redondearBigDecimal(bgdSum_PesItm_MinCal, objParSis.getDecimalesMostrar()), 0, (intNumColIniProAnu+6));//columna de promedio anual calculado
            /* JM 19/Dic/2023  */
            
            bgdSum_PesItm_CanRepCalMax=new BigDecimal(0);
            
            /* JM 19/Dic/2023  */
            bgdSum_PesItm_ProCal=new BigDecimal(0);
            bgdSum_PesItm_MinCal=new BigDecimal(0);
            /* JM 19/Dic/2023  */
        }
        catch(Exception e){
            blnRes=false;
            objUti.mostrarMsgErr_F1(this, e);
        }
        return blnRes;
    }
    
